import React, { useState } from 'react';
import './CodeViewer.css';

const LANGUAGES = [
  { id: 'javascript', label: 'JavaScript', icon: 'js' },
  { id: 'python', label: 'Python', icon: 'py' },
  { id: 'java', label: 'Java', icon: 'java' },
  { id: 'cpp', label: 'C++', icon: 'cpp' },
  { id: 'c', label: 'C', icon: 'c' },
  { id: 'csharp', label: 'C#', icon: 'csharp' },
  { id: 'go', label: 'Go', icon: 'go' },
  { id: 'rust', label: 'Rust', icon: 'rust' },
];

export default function CodeViewer({ codeSnippets, algoLabel }) {
  const [selectedLang, setSelectedLang] = useState('javascript');
  const [copied, setCopied] = useState(false);

  const code = codeSnippets[selectedLang] || '// Code not available';

  const handleCopy = () => {
    navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="code-viewer">
      <div className="code-viewer-header">
        <h3>Code Implementation</h3>
        <div className="code-viewer-actions">
          <button className="code-action-btn" onClick={handleCopy} title="Copy code">
            {copied ? '✓ Copied!' : 'Copy'}
          </button>
        </div>
      </div>

      <div className="language-tabs">
        {LANGUAGES.map(lang => (
          <button
            key={lang.id}
            className={`lang-tab ${selectedLang === lang.id ? 'lang-tab-active' : ''}`}
            onClick={() => setSelectedLang(lang.id)}
          >
            <span className={`lang-icon lang-icon-${lang.icon}`}></span>
            {lang.label}
          </button>
        ))}
      </div>

      <pre className="code-block">
        <code>{code}</code>
      </pre>
    </div>
  );
}
